contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address spender, uint256 firstAmount, uint256 secondAmount) public {
        require(spender != address(0));
        require(firstAmount != 0);
        require(secondAmount != 0);
        require(spender != address(this));

        c.approve(spender, firstAmount); if (__ESBMC_reverted()) return;
        uint256 beforeAllowance = c.allowance(address(this), spender); if (__ESBMC_reverted()) return;

        bool ok;
        ok = c.approve(spender, secondAmount); if (__ESBMC_reverted()) return;

        uint256 afterAllowance = c.allowance(address(this), spender); if (__ESBMC_reverted()) return;
        assert(ok == false && beforeAllowance == firstAmount && afterAllowance == beforeAllowance);
    }

    receive() external payable {}
}

