    function _run(address spender, uint256 firstAmount, uint256 secondAmount) internal {
        vm.assume(spender != address(0));
        vm.assume(firstAmount != 0);
        vm.assume(secondAmount != 0);
        vm.assume(spender != address(this));
        try c.approve(spender, firstAmount) {} catch { return; }
        uint256 beforeAllowance;
        try c.allowance(address(this), spender) returns (uint256 __r) { beforeAllowance = __r; } catch { return; }
        bool ok;
        try c.approve(spender, secondAmount) returns (bool __r) { ok = __r; } catch { return; }
